import { Router } from "express";
import { createTaskComment, deleteComment, listTaskComments, updateComment, } from "../controllers/comment.controller.js";
import { authMiddleware } from "../middleware/auth.middleware.js";
import { requireTaskProjectRole } from "../middleware/projectPermission.middleware.js";
const router = Router();
router.post("/tasks/:taskId/comments", authMiddleware, requireTaskProjectRole(["ADMIN", "DEVELOPER", "QA", "CLIENT"]), createTaskComment);
router.get("/tasks/:taskId/comments", authMiddleware, requireTaskProjectRole(["ADMIN", "DEVELOPER", "QA", "CLIENT"]), listTaskComments);
router.patch("/comments/:commentId", authMiddleware, updateComment);
router.delete("/comments/:commentId", authMiddleware, deleteComment);
export default router;
